import React, { useState } from 'react';
import '../styles/theme.css';

export default function Login({ onLoginSuccess }) {
  const [authMode, setAuthMode] = useState('login'); // 'login', 'signup', 'forgot', 'otp'
  const [formData, setFormData] = useState({
    mobile: '',
    password: '',
    name: '',
    confirmPassword: '',
    otp: ''
  });
  const [message, setMessage] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleLoginSubmit = (e) => {
    e.preventDefault();
    if (!formData.mobile || !formData.password) {
      setMessage('Please enter mobile number and password.');
      return;
    }
    onLoginSuccess();
  };

  const handleSignupSubmit = (e) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      setMessage('Passwords do not match!');
      return;
    }
    alert('Account created successfully! Please login.');
    setAuthMode('login');
    setMessage('');
  };

  const handleSendOtp = (e) => {
    e.preventDefault();
    if (!formData.mobile) {
      setMessage('Please enter your registered mobile number.');
      return;
    }
    alert('OTP sent successfully to ' + formData.mobile + ' (Use 1234)');
    setAuthMode('otp');
    setMessage('');
  };

  const handleVerifyOtp = (e) => {
    e.preventDefault();
    if (formData.otp === '1234') {
      alert('OTP verified! You can now login or reset password.');
      setAuthMode('login');
      setMessage('');
    } else {
      setMessage('Invalid OTP. Use 1234');
    }
  };

  return (
    <div style={pageStyle}>
      
      {/* LEFT PANE - BRANDING */}
      <div style={leftPaneStyle}>
        <div style={{ maxWidth: '400px' }}>
          <div style={{ fontSize: '50px', marginBottom: '10px' }}>🌾</div>
          <h1 style={{ color: '#FFF', fontSize: '36px', margin: '0 0 10px 0', letterSpacing: '1px' }}>RK SONS</h1>
          <p style={{ color: '#A7F3D0', fontSize: '18px', margin: '0 0 30px 0', lineHeight: '1.5' }}>
            Smart Grain Enterprise Management System
          </p>
          <p style={{ color: '#D1FAE5', fontSize: '14px', lineHeight: '1.6', opacity: 0.8 }}>
            Streamline your inventory, manage farmer records, and track daily sales and payments all in one secure platform.
          </p>
        </div>
      </div>

      {/* RIGHT PANE - FORM */}
      <div style={rightPaneStyle}>
        <div style={formContainerStyle}>
          
          <div style={{ marginBottom: '35px' }}>
            <h2 style={{ color: '#111827', margin: '0 0 8px 0', fontSize: '28px', fontWeight: '800' }}>
              {authMode === 'login' && 'Welcome Back'}
              {authMode === 'signup' && 'Create Account'}
              {authMode === 'forgot' && 'Reset Password'}
              {authMode === 'otp' && 'Verify OTP'}
            </h2>
            <p style={{ color: '#6B7280', margin: 0, fontSize: '15px' }}>
              {authMode === 'login' && 'Please enter your details to sign in.'}
              {authMode === 'signup' && 'Join RK Sons enterprise network today.'}
              {authMode === 'forgot' && 'Enter your mobile to receive an OTP.'}
              {authMode === 'otp' && 'We sent a 4-digit code to your mobile.'}
            </p>
          </div>

          {message && <div style={errorStyle}>{message}</div>}

          {/* 1. LOGIN FORM */}
          {authMode === 'login' && (
            <form onSubmit={handleLoginSubmit} style={formStyle}>
              <div>
                <label style={labelStyle}>Mobile Number</label>
                <input type="text" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter your mobile" style={inputStyle} required />
              </div>
              <div>
                <label style={labelStyle}>Password</label>
                <input type="password" name="password" value={formData.password} onChange={handleChange} placeholder="••••••••" style={inputStyle} required />
              </div>
              
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '13px', fontWeight: '600' }}>
                <span style={{ color: '#1B4D3E', cursor: 'pointer' }} onClick={() => { setAuthMode('signup'); setMessage(''); }}>Create Account</span>
                <span style={{ color: '#6B7280', cursor: 'pointer' }} onClick={() => { setAuthMode('forgot'); setMessage(''); }}>Forgot Password?</span>
              </div>

              <button type="submit" style={primaryBtn}>Sign In</button>
            </form>
          )}

          {/* 2. SIGN UP FORM */}
          {authMode === 'signup' && (
            <form onSubmit={handleSignupSubmit} style={formStyle}>
              <div>
                <label style={labelStyle}>Full Name</label>
                <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="Enter your name" style={inputStyle} required />
              </div>
              <div>
                <label style={labelStyle}>Mobile Number</label>
                <input type="text" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter mobile number" style={inputStyle} required />
              </div>
              <div>
                <label style={labelStyle}>Password</label>
                <input type="password" name="password" value={formData.password} onChange={handleChange} placeholder="Create password" style={inputStyle} required />
              </div>
              <div>
                <label style={labelStyle}>Confirm Password</label>
                <input type="password" name="confirmPassword" value={formData.confirmPassword} onChange={handleChange} placeholder="Confirm password" style={inputStyle} required />
              </div>

              <button type="submit" style={primaryBtn}>Register Account</button>
              
              <div style={{ textAlign: 'center', fontSize: '13px', fontWeight: '600', marginTop: '10px' }}>
                <span style={{ color: '#6B7280' }}>Already have an account? </span>
                <span style={{ color: '#1B4D3E', cursor: 'pointer' }} onClick={() => { setAuthMode('login'); setMessage(''); }}>Sign In</span>
              </div>
            </form>
          )}

          {/* 3. FORGOT PASSWORD */}
          {authMode === 'forgot' && (
            <form onSubmit={handleSendOtp} style={formStyle}>
              <div>
                <label style={labelStyle}>Mobile Number</label>
                <input type="text" name="mobile" value={formData.mobile} onChange={handleChange} placeholder="Enter your registered mobile" style={inputStyle} required />
              </div>

              <button type="submit" style={primaryBtn}>Send OTP</button>

              <div style={{ textAlign: 'center', fontSize: '13px', fontWeight: '600', marginTop: '10px' }}>
                <span style={{ color: '#1B4D3E', cursor: 'pointer' }} onClick={() => { setAuthMode('login'); setMessage(''); }}>← Back to Sign In</span>
              </div>
            </form>
          )}

          {/* 4. OTP VERIFICATION */}
          {authMode === 'otp' && (
            <form onSubmit={handleVerifyOtp} style={formStyle}>
              <div>
                <label style={labelStyle}>Enter 4-Digit OTP</label>
                <input type="text" name="otp" value={formData.otp} onChange={handleChange} placeholder="1 2 3 4" maxLength="4" style={{ ...inputStyle, textAlign: 'center', letterSpacing: '12px', fontSize: '20px', fontWeight: 'bold' }} required />
              </div>

              <button type="submit" style={primaryBtn}>Verify & Proceed</button>

              <div style={{ textAlign: 'center', fontSize: '13px', fontWeight: '600', marginTop: '10px' }}>
                <span style={{ color: '#1B4D3E', cursor: 'pointer' }} onClick={() => { setAuthMode('login'); setMessage(''); }}>← Back to Sign In</span>
              </div>
            </form>
          )}

        </div>
      </div>
    </div>
  );
}

// --- MODERN STYLING ---
