const leftPaneStyle = { flex: 1, background: 'linear-gradient(135deg, #0F2027 0%, #1B4D3E 100%)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '40px', boxSizing: 'border-box' };

const rightPaneStyle = { flex: 1, background: '#FFFFFF', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '40px', boxSizing: 'border-box', position: 'relative' };

const formContainerStyle = { width: '100%', maxWidth: '420px' };

const formStyle = { display: 'flex', flexDirection: 'column', gap: '20px' };

const labelStyle = { display: 'block', fontSize: '13px', fontWeight: '600', color: '#374151', marginBottom: '8px' };

const inputStyle = { width: '100%', padding: '14px 16px', borderRadius: '10px', border: '1.5px solid #E5E7EB', background: '#F9FAFB', fontSize: '15px', color: '#111827', outline: 'none', boxSizing: 'border-box', transition: 'all 0.2s ease-in-out' };

const primaryBtn = { background: 'linear-gradient(135deg, #1B4D3E 0%, #256A55 100%)', color: '#FFF', border: 'none', padding: '14px', borderRadius: '10px', fontWeight: 'bold', fontSize: '15px', cursor: 'pointer', width: '100%', marginTop: '10px', boxShadow: '0 4px 14px rgba(27, 77, 62, 0.25)', transition: 'transform 0.1s ease' };

const errorStyle = { background: '#FEF2F2', color: '#991B1B', padding: '12px 16px', borderRadius: '8px', fontSize: '13px', marginBottom: '20px', border: '1px solid #F87171', fontWeight: '500' };
